function PageHeader({ eyebrow, title, desc, action }: any) { return <div className="page-header"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{desc}</p></div>{action}</div>; }
function ProjectsPage({ data, locale, t, setModal, notify }: any) {
  const [category, setCategory] = useState('All'); const [query, setQuery] = useState('');
  const categories = ['All', 'Infrastructure', 'Technology', 'Real Estate', 'Mobility'];
  const projects = data.projects.filter((p: any) => (category === 'All' || p.category === category) && (p.title[locale] || p.title.en).toLowerCase().includes(query.toLowerCase()));
  return <><PageHeader eyebrow="DISCOVER · RESEARCH PROJECTS" title={t('projectExplorer')} desc="Explore illustrative projects and see how the investment workflow is presented." action={<button className="btn btn-primary" onClick={() => notify(t('investDisclaimer'))}><Sparkles size={15}/>How it works</button>}/><div className="filter-row"><div className="filter-pills">{categories.map(c => <button className={category === c ? 'active' : ''} onClick={() => setCategory(c)} key={c}>{c}</button>)}</div><div className="search-field"><Search size={15}/><input placeholder="Search projects" value={query} onChange={e => setQuery(e.target.value)}/></div></div><div className="project-grid">{projects.map((p: any, i: number) => <article className={`project-card project-tone-${i % 4}`} key={p.id}><div className="project-cover"><span>{p.category}</span><div className="project-cover-shape">{i % 2 === 0 ? <Rocket/> : <Building2/>}</div><b>{p.id}</b></div><div className="project-card-body"><div className="project-card-heading"><h3>{p.title[locale] || p.title.en}</h3><span className={`status-pill ${p.status}`}>{p.status}</span></div><p>{p.description[locale] || p.description.en}</p><div className="project-meta"><span>{t('minimum')} <b>{money(p.minimum, locale)}</b></span><span>{t('duration')} <b>{p.duration}</b></span></div><div className="funding-line"><span>{t('raised')}</span><b>{Math.round((p.raised / Math.max(1, p.target)) * 100)}%</b></div><div className="progress-track"><i style={{ width: `${Math.min(100, (p.raised / Math.max(1, p.target)) * 100)}%` }}/></div><div className="project-card-foot"><small>{money(p.raised, locale)} of {money(p.target, locale)}</small><button className="btn btn-outline" onClick={() => setModal('project')}>{t('details')}<ArrowRight size={13}/></button></div></div></article>)}</div><div className="disclaimer-wide"><ShieldCheck size={17}/>{t('investDisclaimer')}</div></>;
}
function WalletPage({ data, user, locale, t, setModal }: any) {
  const [tab, setTab] = useState('all'); const history = data.activity.filter((a: any) => a.userId === user.id);
  return <><PageHeader eyebrow="ACCOUNT · WALLET" title={t('wallet')} desc="Your simulated wallet balances and transaction activity." action={<button className="btn btn-primary" onClick={() => setModal('deposit')}><Plus size={15}/>{t('deposit')}</button>}/><div className="wallet-overview"><div className="wallet-balance-card"><span>{t('totalBalance')}</span><strong>{money(user.wallet.available + user.wallet.invested + user.wallet.locked + user.wallet.bonus, locale)}</strong><small><ShieldCheck size={13}/> Simulated demo balance</small><div className="wallet-actions"><button className="btn btn-light" onClick={() => setModal('deposit')}><ArrowDownLeft size={15}/>{t('deposit')}</button><button className="btn btn-outline-light" onClick={() => alert('Withdrawals are disabled in this research demo.')}><ArrowUpRight size={15}/>{t('withdraw')}</button></div></div><div className="wallet-balance-side"><StatCard icon={<Wallet/>} label={t('available')} value={money(user.wallet.available, locale)} accent="green"/><StatCard icon={<Lock/>} label={t('locked')} value={money(user.wallet.locked, locale)} accent="orange"/><StatCard icon={<BarChart3/>} label={t('invested')} value={money(user.wallet.invested, locale)} accent="blue"/></div></div><section className="content-card"><div className="content-card-head"><div><h3>{t('walletLedger')}</h3><p>All actions shown here are test records.</p></div><div className="filter-pills small-pills">{['all','deposit','investment','adjustment'].map(v => <button className={tab === v ? 'active' : ''} onClick={() => setTab(v)} key={v}>{v === 'all' ? 'All' : v}</button>)}</div></div><div className="data-table-wrap"><table className="data-table"><thead><tr><th>Reference</th><th>Description</th><th>Date</th><th>Type</th><th>Amount</th></tr></thead><tbody>{history.filter((h: any) => tab === 'all' || h.type === tab).map((h: any) => <tr key={h.id}><td>{h.id}</td><td>{h.description}</td><td>{dateText(h.createdAt, locale)}</td><td><span className={`status-pill ${h.type}`}>{h.type}</span></td><td className={h.amount >= 0 ? 'amount-positive' : 'amount-negative'}>{h.amount >= 0 ? '+' : ''}{money(h.amount, locale)}</td></tr>)}</tbody></table></div></section><div className="disclaimer-wide"><Clock3 size={17}/>Deposit requests are manually reviewed. The demo does not verify blockchain transfers or process real payments.</div></>;
}
function InvestmentsPage({ data, user, locale, t }: any) { const rows = data.investments.filter((i: any) => i.userId === user.id); return <><PageHeader eyebrow="PORTFOLIO · ALLOCATION" title={t('investments')} desc="Track your sample allocations project by project."/><div className="stat-grid four"><StatCard icon={<Briefcase/>} label={t('invested')} value={money(user.wallet.invested, locale)} accent="blue"/><StatCard icon={<TrendingUp/>} label="Realized demo profit" value={money(rows.reduce((s: number, r: any) => s + r.realized, 0), locale)} accent="green"/><StatCard icon={<Clock3/>} label="Expected (illustrative)" value={money(rows.reduce((s: number, r: any) => s + r.expected, 0), locale)} accent="orange"/><StatCard icon={<LayersIcon/>} label="Active allocations" value={String(rows.length)} accent="purple"/></div><div className="investment-list">{rows.map((r: any) => { const p = data.projects.find((x: any) => x.id === r.projectId); return <div className="investment-row" key={r.id}><div className="investment-icon"><Building2/></div><div className="investment-main"><b>{p?.title[locale] || p?.title.en || r.projectId}</b><small>{r.id} · Started {dateText(r.date, locale)}</small></div><div><small>Allocated</small><b>{money(r.amount, locale)}</b></div><div><small>Realized demo</small><b className="amount-positive">+{money(r.realized, locale)}</b></div><span className="status-pill active">{r.status}</span></div>; })}</div><div className="disclaimer-wide"><ShieldCheck size={17}/>Expected and realized values are illustrative data, not a promise or payable return.</div></>; }
