function LotteryPage({ t, notify }: any) { return <><PageHeader eyebrow="COMMUNITY · DRAW EVENTS" title={t('lottery')} desc="Explore the sample draw experience. No paid tickets or real prizes are available."/><div className="lottery-hero"><div><div className="eyebrow">X3 COMMUNITY DRAW</div><h2>One community.<br/>Many possibilities.</h2><p>Follow sample draw rounds, learn the ticket flow, and explore the participation interface.</p><button className="btn btn-light" onClick={() => notify('Ticket purchase is disabled in this research demo.')}>Explore sample draws <ArrowRight size={15}/></button></div><div className="lottery-token"><Ticket size={85}/><b>XB</b><span>DRAW</span></div></div><div className="lottery-grid">{[1,3,5,10].map((n,i) => <div className="lottery-card" key={n}><span className="lottery-ticket-icon"><Ticket/></span><small>DEMO ROUND {i+1}</small><h3>${n} <span>ticket concept</span></h3><strong>${(n*1000).toLocaleString()}</strong><small>Illustrative prize amount · not payable</small><button className="btn btn-outline" onClick={() => notify(t('lotteryDisclaimer'))}>View details <ArrowRight size={13}/></button></div>)}</div><div className="disclaimer-wide"><ShieldCheck size={17}/>{t('lotteryDisclaimer')}</div></>; }
function LoansPage({ t }: any) { return <><PageHeader eyebrow="CREDIT · SIMULATION" title={t('loans')} desc="Review how a collateral-backed loan interface could be presented."/><div className="loan-panel"><div className="loan-icon"><HandCoins size={34}/></div><div><h2>Loan center</h2><p>{t('loanDisclaimer')}</p></div><span className="status-pill paused">Disabled in demo</span></div><div className="stat-grid three"><StatCard icon={<Lock/>} label="Collateral" value="$0.00" accent="orange"/><StatCard icon={<CircleDollarSign/>} label="Outstanding" value="$0.00" accent="blue"/><StatCard icon={<CheckCircle2/>} label="Repaid" value="$0.00" accent="green"/></div></>; }
function RewardsPage({ user, t, notify }: any) { return <><PageHeader eyebrow="COMMUNITY · INVITATIONS" title={t('rewards')} desc="An example of the referral and mission experience."/><div className="referral-hero"><div><div className="eyebrow">YOUR INVITE LINK</div><h2>Grow your network<br/>with XBank.</h2><p>Share your demo invite link. Referral credit is not withdrawable or redeemable in this prototype.</p><div className="referral-link"><code>https://xbank.demo/join/alex1001</code><button onClick={() => { navigator.clipboard?.writeText('https://xbank.demo/join/alex1001'); notify(t('copied')); }}><Copy size={14}/>{t('copyLink')}</button></div></div><div className="referral-graphic"><Users size={70}/><b>{user.referralCount}</b><small>DIRECT INVITES</small></div></div><div className="stat-grid three"><StatCard icon={<Users/>} label="Direct referrals" value={String(user.referralCount)} accent="blue"/><StatCard icon={<Gift/>} label={t('referralEarnings')} value={money(user.wallet.bonus)} accent="green"/><StatCard icon={<Crown/>} label={t('level')} value={`Level ${user.level}`} accent="orange"/></div><div className="content-card mission-card"><div className="content-card-head"><div><h3>{t('missions')}</h3><p>Complete profile and product exploration tasks in this demo.</p></div><span className="status-pill active">3 active</span></div>{[{n:'Complete your profile',p:80,pts:100},{n:'Explore 3 sample projects',p:66,pts:50},{n:'Review the wallet guide',p:0,pts:25}].map(m => <div className="mission-row" key={m.n}><div><b>{m.n}</b><small>{m.pts} points</small></div><div className="mission-progress"><span>{m.p}%</span><div className="progress-track"><i style={{width:`${m.p}%`}}/></div></div><button className="btn btn-outline" onClick={()=>notify(m.p === 100 ? 'This mission is already completed.' : 'Mission checklist opened in demo mode.')}>{m.p === 100 ? 'Completed' : 'Continue'}</button></div>)}</div></>; }
